const serviceIcons=['plane','truck','ship','project','box','warehouse','exhibition','moving'];
const readStorage=key=>{try{return localStorage.getItem(key)}catch{return null}};
const writeStorage=(key,value)=>{try{localStorage.setItem(key,value)}catch{}};
const requestedLanguage=new URLSearchParams(location.search).get('lang');
let language=['en','ar'].includes(requestedLanguage)?requestedLanguage:(readStorage('maxline-language')==='ar'?'ar':'en');
let dark=readStorage('maxline-theme')?readStorage('maxline-theme')==='dark':window.matchMedia('(prefers-color-scheme: dark)').matches;
function setTheme(){document.documentElement.dataset.theme=dark?'dark':'light';const b=document.getElementById('theme');b.innerHTML=icon(dark?'sun':'moon');b.setAttribute('aria-label',content[language][dark?'light':'dark']);b.title=content[language][dark?'light':'dark']}
function setLanguage(lang){language=lang;const c=content[lang];document.documentElement.lang=lang;document.documentElement.dir=lang==='ar'?'rtl':'ltr';document.querySelectorAll('[data-i18n]').forEach(el=>{el.innerHTML=c[el.getAttribute('data-i18n')]});['en','ar'].forEach(l=>document.getElementById(l).setAttribute('aria-pressed',String(l===lang)));document.querySelector('.language').setAttribute('aria-label',lang==='ar'?'اللغة':'Language');document.querySelectorAll('.website,.brand').forEach(el=>el.href='https://maxlineglobal.com/'+lang);document.querySelector('.brand').setAttribute('aria-label',c.visit+' — '+c.companyPlain);document.querySelectorAll('.brand img').forEach(el=>el.alt=c.companyPlain);document.getElementById('qr-link').setAttribute('aria-label',c.qrLabel);document.querySelector('.dialog-close').setAttribute('aria-label',c.close);document.getElementById('copy-url').setAttribute('aria-label',c.urlLabel);document.getElementById('services').innerHTML=c.serviceNames.map((s,i)=>'<div class="service"><i>'+icon(serviceIcons[i])+'</i><span>'+s+'</span></div>').join('');document.getElementById('countries').innerHTML=c.countries.map(s=>'<span class="country">'+s+'</span>').join('');document.title=lang==='ar'?'أبارنا بافيثران | ماكس لاين للحلول اللوجستية العالمية':'Aparna Pavithran | Maxline Global Logistic Solutions';writeStorage('maxline-language',lang);setTheme();refreshQr()}
renderIcons();
document.getElementById('en').addEventListener('click',()=>setLanguage('en'));document.getElementById('ar').addEventListener('click',()=>setLanguage('ar'));document.getElementById('theme').addEventListener('click',()=>{dark=!dark;writeStorage('maxline-theme',dark?'dark':'light');setTheme()});
// The live origin and path are used after deployment, without tracking parameters.
const baseCardUrl=location.protocol==='file:'?'https://aparna-maxline.funoonprintco.com/':new URL(location.pathname,location.origin).href;
function currentCardUrl(){const u=new URL(baseCardUrl);u.searchParams.set('lang',language);return u.href}
let toastTimer;function toast(message){const el=document.getElementById('toast');el.textContent=message;el.classList.add('visible');clearTimeout(toastTimer);toastTimer=setTimeout(()=>el.classList.remove('visible'),3000)}
async function shareCard(){const cardUrl=currentCardUrl();if(navigator.share){try{await navigator.share({title:'Aparna Pavithran | Maxline',text:content[language].companyPlain,url:cardUrl});return}catch(error){if(error.name==='AbortError')return}}try{if(!navigator.clipboard)throw new Error('Clipboard unavailable');await navigator.clipboard.writeText(cardUrl);toast(content[language].copied)}catch{const dialog=document.getElementById('copy-dialog');document.getElementById('copy-url').value=cardUrl;dialog.showModal();document.getElementById('copy-url').select()}}
document.querySelectorAll('.share').forEach(b=>b.addEventListener('click',shareCard));
let qrSvg='';
function refreshQr(){
 const cardUrl=currentCardUrl(),qr=qrcode(0,'H');qr.addData(cardUrl);qr.make();
 const n=qr.getModuleCount(),size=n+8;
 let shapes='<rect width="'+size+'" height="'+size+'" fill="white"/>';
 for(let y=0;y<n;y++)for(let x=0;x<n;x++){
  if((x<7&&y<7)||(x>=n-7&&y<7)||(x<7&&y>=n-7))continue;
  if(qr.isDark(y,x))shapes+='<rect x="'+(x+4)+'" y="'+(y+4)+'" width="1" height="1" rx=".23" fill="#0B1220"/>';
 }
 for(const [x,y] of [[4,4],[n-3,4],[4,n-3]]){
  shapes+='<rect x="'+x+'" y="'+y+'" width="7" height="7" rx="1.2" fill="#0B1220"/><rect x="'+(x+1)+'" y="'+(y+1)+'" width="5" height="5" rx=".7" fill="white"/><rect x="'+(x+2)+'" y="'+(y+2)+'" width="3" height="3" rx=".5" fill="#0B1220"/>';
 }
 qrSvg='<svg xmlns="http://www.w3.org/2000/svg" viewBox="0 0 '+size+' '+size+'" style="stroke:none" aria-hidden="true">'+shapes+'</svg>';
 document.getElementById('qr').innerHTML=qrSvg;document.getElementById('qr-link').href=cardUrl;
}
document.getElementById('download-qr').addEventListener('click',()=>{
 const image=new Image();const source=URL.createObjectURL(new Blob([qrSvg],{type:'image/svg+xml'}));
 image.onload=()=>{const canvas=document.createElement('canvas');canvas.width=canvas.height=2000;canvas.getContext('2d').drawImage(image,0,0,2000,2000);URL.revokeObjectURL(source);canvas.toBlob(blob=>{if(!blob)return;const url=URL.createObjectURL(blob),a=document.createElement('a');a.href=url;a.download='Aparna-Pavithran-Maxline-QR-'+language+'.png';a.click();setTimeout(()=>URL.revokeObjectURL(url),30000)},'image/png')};image.src=source;
});
setLanguage(language);
